/* kui font slots and font packs: the reference six text fonts (reg/bold at 8, 10 and 12) are read through kui_slot(), and
 * Appearances > Font (the ui.font setting) swaps them as the reference FontRegistry::applyFontPack does. Helvetica is the built-in
 * set (the reference default); the other packs are the BMF tables of assets/fonts (font_pack_*.c, generated by forge/tools/bmf2c.ts). */
#include <string.h>

#include "pal/kui.h"

extern const kui_font_t FONT_PK_HAXR_REG8, FONT_PK_HAXR_BOLD8, FONT_PK_HAXR_REG10, FONT_PK_HAXR_BOLD10, FONT_PK_HAXR_REG12,
    FONT_PK_HAXR_BOLD12;
extern const kui_font_t FONT_PK_PROF_REG8, FONT_PK_PROF_BOLD8, FONT_PK_PROF_REG10, FONT_PK_PROF_BOLD10, FONT_PK_PROF_REG12,
    FONT_PK_PROF_BOLD12;

/* The packs in menu order (Helvetica first, the reference default); the names are the values of ui.font. */
typedef struct {
    const char *name;
    const kui_font_t *slot[KUI_F_COUNT];
} font_pack_t;

#define PACK(n, p)                                                                                                    \
    {n, {&FONT_PK_##p##_REG8, &FONT_PK_##p##_BOLD8, &FONT_PK_##p##_REG10, &FONT_PK_##p##_BOLD10, &FONT_PK_##p##_REG12, \
         &FONT_PK_##p##_BOLD12}}

static const font_pack_t PACKS[] = {
    {"Helvetica", {&FONT_REG8, &FONT_BOLD8, &FONT_REG10, &FONT_BOLD10, &FONT_REG12, &FONT_BOLD12}},
    PACK("Haxrcorp4089", HAXR),
    PACK("ProFont", PROF),
};
#define NPACKS ((int)(sizeof(PACKS) / sizeof(PACKS[0])))

static int s_pack; /* index into PACKS */

const kui_font_t *kui_slot(kui_slot_t s) {
    if ((unsigned)s >= KUI_F_COUNT) s = KUI_F_REG8;
    return PACKS[s_pack].slot[s];
}

int kui_font_pack_count(void) { return NPACKS; }

const char *kui_font_pack_at(int i) { return (i >= 0 && i < NPACKS) ? PACKS[i].name : NULL; }

const char *kui_font_pack_name(void) { return PACKS[s_pack].name; }

bool kui_font_pack_set(const char *name) {
    if (!name || !*name) name = PACKS[0].name;
    for (int i = 0; i < NPACKS; i++) {
        if (strcmp(PACKS[i].name, name) == 0) {
            s_pack = i;
            return true;
        }
    }
    return false;
}
